package com.internetter.overheadscalecolor;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class OverheadScaleColorPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(OverheadScaleColorPlugin.class);
		RuneLite.main(args);
	}
}

package com.internetter.overheadscalecolor;

import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.MAGIC;
import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.MELEE;
import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.NO_RING;
import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.RANGED;
import static com.internetter.overheadscalecolor.OverheadScaleColorOverlay.ringSlotFor;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.HeadIcon;
import org.junit.Test;

/**
 * Pins the HeadIcon -> ring mapping.
 *
 * Worth a test because a mistake here is invisible: a wrongly-ringed overhead still looks like a
 * perfectly plausible plugin, so nothing about it draws attention. The rule is that only the three
 * protection prayers and their Deflect equivalents are ringed, and everything else renders ringless
 * rather than being assigned an invented color.
 */
public class RingSlotTest
{
	@Test
	public void protectionPrayersAndTheirDeflectEquivalentsShareASlot()
	{
		assertEquals(MELEE, ringSlotFor(HeadIcon.MELEE));
		assertEquals(MELEE, ringSlotFor(HeadIcon.DEFLECT_MELEE));

		assertEquals(RANGED, ringSlotFor(HeadIcon.RANGED));
		assertEquals(RANGED, ringSlotFor(HeadIcon.DEFLECT_RANGE));

		assertEquals(MAGIC, ringSlotFor(HeadIcon.MAGIC));
		assertEquals(MAGIC, ringSlotFor(HeadIcon.DEFLECT_MAGE));
	}

	@Test
	public void combinedAndNonProtectionOverheadsGetNoRing()
	{
		final Set<HeadIcon> ringless = EnumSet.of(
			// Combined overheads: no single correct color.
			HeadIcon.RANGE_MAGE,
			HeadIcon.RANGE_MELEE,
			HeadIcon.MAGE_MELEE,
			HeadIcon.RANGE_MAGE_MELEE,
			// Not protection prayers at all.
			HeadIcon.SMITE,
			HeadIcon.RETRIBUTION,
			HeadIcon.REDEMPTION,
			HeadIcon.WRATH,
			HeadIcon.SOUL_SPLIT);

		for (HeadIcon icon : ringless)
		{
			assertEquals("expected no ring for " + icon, NO_RING, ringSlotFor(icon));
		}
	}

	/**
	 * Guards against a new HeadIcon appearing in a future API version and silently falling into the
	 * default branch unnoticed. If this fails, decide deliberately whether the new icon is ringed.
	 */
	@Test
	public void everyHeadIconIsAccountedFor()
	{
		assertEquals("HeadIcon gained or lost values; revisit the ring mapping",
			15, HeadIcon.values().length);

		for (HeadIcon icon : HeadIcon.values())
		{
			final int slot = ringSlotFor(icon);
			assertNotNull(icon.name(), icon);
			if (slot != NO_RING && (slot < MELEE || slot > MAGIC))
			{
				throw new AssertionError("slot out of range for " + icon + ": " + slot);
			}
		}
	}
}

package com.internetter.overheadscalecolor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.HeadIcon;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the scaled overhead icon and its colored ring.
 *
 * Icons come from sprite archive {@link SpriteID#HEADICONS_PRAYER} (440), indexed by
 * {@link HeadIcon#ordinal()}. The enum has exactly 15 values, matching that archive's file count,
 * and icons render correctly in game -- but the correspondence is inferred rather than documented,
 * and has not been checked prayer by prayer.
 *
 * Nothing in {@link #render(Graphics2D)} allocates: scaled images, ring colors and strokes are all
 * memoised and rebuilt only on config change.
 */
@Slf4j
public class OverheadScaleColorOverlay extends Overlay
{
	/** Ring outline. Softened black -- pure black reads as a hard edge at 1px. */
	private static final Color RING_OUTLINE = new Color(0, 0, 0, 180);

	/** Ring slots. Also index the color and stroke arrays. */
	static final int MELEE = 0;
	static final int RANGED = 1;
	static final int MAGIC = 2;
	static final int NO_RING = -1;

	private final Client client;
	private final OverheadScaleColorConfig config;
	private final SpriteManager spriteManager;

	/** Scaled images, memoised per (icon ordinal, scale, interpolation). */
	private final Map<Long, BufferedImage> scaledCache = new HashMap<>();

	/** Native (unscaled) sprites, memoised per icon ordinal. Never holds null -- see below. */
	private final Map<Integer, BufferedImage> nativeCache = new HashMap<>();

	private final Color[] ringColors = new Color[3];
	private final Stroke[] ringStrokes = new Stroke[3];
	private final Stroke[] outlineStrokes = new Stroke[3];
	private boolean ringStateValid;

	/** Bitmask of icon ordinals already logged as missing, so the log is not written per frame. */
	private int missingLogged;

	@Inject
	OverheadScaleColorOverlay(Client client, OverheadScaleColorConfig config, SpriteManager spriteManager)
	{
		this.client = client;
		this.config = config;
		this.spriteManager = spriteManager;
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
	}

	/**
	 * Invalidation is requested from the AWT event thread (config changes and plugin lifecycle both
	 * arrive there) but the caches are read and written by {@link #render(Graphics2D)} on the client
	 * thread. Clearing them directly would be concurrent mutation of a plain HashMap, so these only
	 * raise a flag and the client thread does the actual clearing at the top of the next frame.
	 */
	private volatile boolean invalidatePending;
	private volatile boolean fullInvalidatePending;

	/** Config changed: drop derived state, keep the native sprites. */
	void invalidate()
	{
		invalidatePending = true;
	}

	/**
	 * Plugin stopping: drop everything. The plugin instance and this overlay survive a
	 * disable/enable cycle in RuneLite, so the sprites are dropped too rather than left to go stale.
	 */
	void invalidateAll()
	{
		fullInvalidatePending = true;
	}

	/** Must only be called on the client thread. */
	private void applyPendingInvalidation()
	{
		if (fullInvalidatePending)
		{
			fullInvalidatePending = false;
			invalidatePending = false;
			nativeCache.clear();
			scaledCache.clear();
			ringStateValid = false;
			missingLogged = 0;
		}
		else if (invalidatePending)
		{
			invalidatePending = false;
			scaledCache.clear();
			ringStateValid = false;
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		applyPendingInvalidation();

		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		final HeadIcon icon = local.getOverheadIcon();
		if (icon == null)
		{
			return null;
		}

		final BufferedImage nativeImg = nativeSprite(icon);
		if (nativeImg == null)
		{
			return null;
		}

		final BufferedImage img = scaled(icon, nativeImg, config.scale(), config.smoothScaling());
		final LocalPoint lp = local.getLocalLocation();
		if (lp == null)
		{
			return null;
		}

		final int zOffset = local.getLogicalHeight() + config.heightOffset();

		// getCanvasImageLocation centres the image on the projected point in BOTH axes (verified
		// by decompiling Perspective). A naive scale-down therefore shrinks toward the centre and
		// the bottom edge rises; shifting down by half the height difference pins the bottom edge,
		// which keeps the icon anchored where vanilla put it at every scale.
		final Point p = Perspective.getCanvasImageLocation(client, lp, img, zOffset);
		if (p == null)
		{
			return null;
		}

		final int x = p.getX();
		final int y = p.getY() + (nativeImg.getHeight() - img.getHeight()) / 2;

		if (config.ringEnabled())
		{
			drawRing(graphics, icon, x, y, img.getWidth(), img.getHeight());
		}

		graphics.drawImage(img, x, y, null);
		return null;
	}

	/**
	 * The ring is stroked at render time rather than baked into the cached image deliberately. Its
	 * whole purpose is legibility at small scales, and baking it in would shrink it along with the
	 * icon -- thinnest exactly when it matters most. Thickness is in screen pixels instead.
	 */
	private void drawRing(Graphics2D graphics, HeadIcon icon, int x, int y, int w, int h)
	{
		final int slot = ringSlotFor(icon);
		if (slot < 0)
		{
			return;
		}

		if (!ringStateValid)
		{
			refreshRingState();
		}

		final int radius = Math.max(w, h) / 2 + config.ringGap();
		final int diameter = radius * 2;
		final int left = x + w / 2 - radius;
		final int top = y + h / 2 - radius;

		final Object priorAA = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		final Stroke priorStroke = graphics.getStroke();

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		if (config.ringOutline())
		{
			graphics.setStroke(outlineStrokes[slot]);
			graphics.setColor(RING_OUTLINE);
			graphics.drawOval(left, top, diameter, diameter);
		}

		graphics.setStroke(ringStrokes[slot]);
		graphics.setColor(ringColors[slot]);
		graphics.drawOval(left, top, diameter, diameter);

		graphics.setStroke(priorStroke);
		if (priorAA != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, priorAA);
		}
	}

	/**
	 * Resolve palette colors and build strokes once per config change. Reading a Color back from
	 * ConfigManager parses a string and allocates, so doing this per frame would allocate on every
	 * render.
	 */
	private void refreshRingState()
	{
		final RingPalette palette = config.palette();
		if (palette == RingPalette.CUSTOM)
		{
			ringColors[MELEE] = config.meleeColor();
			ringColors[RANGED] = config.rangedColor();
			ringColors[MAGIC] = config.magicColor();
		}
		else
		{
			ringColors[MELEE] = palette.melee();
			ringColors[RANGED] = palette.ranged();
			ringColors[MAGIC] = palette.magic();
		}

		final float thickness = config.ringThickness();
		final float outline = thickness + 2f;

		if (config.distinctStyles())
		{
			// A cue that survives total color loss: melee solid, ranged dashed, magic dotted.
			// Dash lengths scale with thickness so the pattern stays legible as it thickens.
			final float[] dashed = {thickness * 2.5f, thickness * 2f};
			final float[] dotted = {0.1f, thickness * 2.6f};

			ringStrokes[MELEE] = new BasicStroke(thickness);
			ringStrokes[RANGED] = new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 1f, dashed, 0f);
			ringStrokes[MAGIC] = new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, dotted, 0f);

			// The outline follows the same dash pattern; a solid dark ring underneath would swamp
			// the shape cue this option exists to provide.
			outlineStrokes[MELEE] = new BasicStroke(outline);
			outlineStrokes[RANGED] = new BasicStroke(outline, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 1f, dashed, 0f);
			outlineStrokes[MAGIC] = new BasicStroke(outline, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, dotted, 0f);
		}
		else
		{
			final Stroke ring = new BasicStroke(thickness);
			final Stroke out = new BasicStroke(outline);
			for (int i = 0; i < 3; i++)
			{
				ringStrokes[i] = ring;
				outlineStrokes[i] = out;
			}
		}

		ringStateValid = true;
	}

	/**
	 * Which ring slot an icon uses, or -1 for icons that render ringless.
	 *
	 * Deflect variants share their protection-prayer equivalent's slot. Combined overheads and the
	 * non-protection prayers (Smite, Retribution, Redemption, Wrath, Soul Split) get no ring rather
	 * than an invented color.
	 */
	static int ringSlotFor(HeadIcon icon)
	{
		switch (icon)
		{
			case MELEE:
			case DEFLECT_MELEE:
				return MELEE;
			case RANGED:
			case DEFLECT_RANGE:
				return RANGED;
			case MAGIC:
			case DEFLECT_MAGE:
				return MAGIC;
			default:
				return NO_RING;
		}
	}

	private BufferedImage nativeSprite(HeadIcon icon)
	{
		final int index = icon.ordinal();
		final BufferedImage cached = nativeCache.get(index);
		if (cached != null)
		{
			return cached;
		}

		final BufferedImage img = spriteManager.getSprite(SpriteID.HEADICONS_PRAYER, index);
		if (img == null)
		{
			// Deliberately NOT cached. getSprite returns null while the client's sprite cache is
			// still warming up, and caching that would permanently blank this icon for the rest of
			// the session. Retrying costs a map lookup per frame until it resolves.
			if ((missingLogged & (1 << index)) == 0)
			{
				missingLogged |= 1 << index;
				log.debug("no sprite yet for HeadIcon {} (archive {} index {})", icon, SpriteID.HEADICONS_PRAYER, index);
			}
			return null;
		}

		nativeCache.put(index, img);
		return img;
	}

	private BufferedImage scaled(HeadIcon icon, BufferedImage src, int scalePercent, boolean smooth)
	{
		final long key = ((long) icon.ordinal() << 32) | ((long) scalePercent << 1) | (smooth ? 1 : 0);
		final BufferedImage cached = scaledCache.get(key);
		if (cached != null)
		{
			return cached;
		}

		if (scalePercent == 100)
		{
			scaledCache.put(key, src);
			return src;
		}

		final int w = Math.max(1, src.getWidth() * scalePercent / 100);
		final int h = Math.max(1, src.getHeight() * scalePercent / 100);

		final BufferedImage dst = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = dst.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			smooth ? RenderingHints.VALUE_INTERPOLATION_BILINEAR : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(src, 0, 0, w, h, null);
		g.dispose();

		scaledCache.put(key, dst);
		return dst;
	}
}

package com.internetter.overheadscalecolor;

import java.awt.Color;

/**
 * Ring colour presets, including palettes chosen for the common forms of colour vision
 * deficiency (CVD).
 *
 * Why presets rather than "just shift the green a bit": a dichromat's colour space is effectively
 * two-dimensional -- one surviving hue axis plus luminance. Three categories separated only by hue
 * cannot be made reliable by nudging the shades. Each palette below therefore separates the three
 * prayer types on BOTH the surviving hue axis and luminance, and avoids the confusable pair
 * entirely rather than trying to fine-tune it.
 *
 * Colours are drawn from the Okabe-Ito qualitative palette where possible, which is the
 * long-standing reference set for CVD-safe categorical encoding.
 *
 * For anyone whose vision is not served by any of these, {@link #CUSTOM} hands all three colours
 * back to the user, and the "distinct ring styles" option adds a non-colour cue on top.
 */
public enum RingPalette
{
	/**
	 * Standard palette. Intuitive mapping, but red/green is precisely the pair lost in the most
	 * common deficiencies, so it is not a safe default for everyone.
	 */
	STANDARD("Standard", 0xFF4136, 0x2ECC40, 0x2E9BFF),

	/**
	 * Deuteranopia / deuteranomaly and protanopia / protanomaly -- red-green deficiency, by far the
	 * most common form (roughly 8% of men, 0.5% of women). Green is dropped entirely. Separation is
	 * orange (mid luminance, yellow axis) / white (max luminance, no hue) / blue (low luminance,
	 * blue axis), which survives both deutan and protan simulation.
	 */
	RED_GREEN("Red-green friendly (deuteran / protan)", 0xE69F00, 0xFFFFFF, 0x0072B2),

	/**
	 * Tritanopia / tritanomaly -- blue-yellow deficiency. Rare. Here red and green are reliable but
	 * blue/green and yellow/violet converge, so blue is dropped and magic moves to magenta.
	 */
	BLUE_YELLOW("Blue-yellow friendly (tritan)", 0xD55E00, 0x009E73, 0xCC79A7),

	/**
	 * Achromatopsia / monochromacy, and anyone who simply wants maximum contrast. Pure luminance
	 * separation. Enable "distinct ring styles" alongside this -- with no hue at all, the dash
	 * pattern is doing most of the work.
	 */
	MONOCHROME("Monochrome / high contrast", 0xFFFFFF, 0xA0A0A0, 0x4A4A4A),

	/** Use the three colour pickers below instead of a preset. */
	CUSTOM("Custom colors", 0, 0, 0);

	private final String label;
	private final Color melee;
	private final Color ranged;
	private final Color magic;

	RingPalette(String label, int melee, int ranged, int magic)
	{
		this.label = label;
		this.melee = new Color(melee);
		this.ranged = new Color(ranged);
		this.magic = new Color(magic);
	}

	Color melee()
	{
		return melee;
	}

	Color ranged()
	{
		return ranged;
	}

	Color magic()
	{
		return magic;
	}

	/** RuneLite renders enum config items using toString(). */
	@Override
	public String toString()
	{
		return label;
	}
}

package com.internetter.overheadscalecolor;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Config keys are an API: renaming one after release silently resets every user's saved settings.
 * Add to this interface sparingly -- see the "Scope" section of DESIGN.md.
 */
@ConfigGroup(OverheadScaleColorConfig.GROUP)
public interface OverheadScaleColorConfig extends Config
{
	String GROUP = "overheadscalecolor";

	@ConfigSection(
		name = "Ring",
		description = "Colored ring drawn around the overhead icon.",
		position = 20
	)
	String RING_SECTION = "ring";

	@ConfigItem(
		position = 1,
		keyName = "scale",
		name = "Scale %",
		description = "Rendered size as a percent of native size. 100 is vanilla size; the floor is 10 because the source sprite is only ~30px tall and anything smaller stops rendering at all."
	)
	@Range(min = 10, max = 100)
	default int scale()
	{
		return 50;
	}

	@ConfigItem(
		position = 2,
		keyName = "heightOffset",
		name = "Height offset",
		description = "Raises the icon above your head. The player's logical height alone sits it too low, so the default is 40."
	)
	@Range(min = -200, max = 200)
	default int heightOffset()
	{
		return 40;
	}

	@ConfigItem(
		position = 3,
		keyName = "hideOnlyWhilePraying",
		name = "Only hide while praying",
		description =
			"The client draws your icon, healthbar, hitsplats, overhead chat and name in a single pass that can only be suppressed as a whole, "
				+ "so replacing the icon also hides those. With this ON that cost applies only while an overhead prayer is active, and everything "
				+ "is normal the rest of the time. Turn it OFF only if you find the switch-over distracting."
	)
	default boolean hideOnlyWhilePraying()
	{
		return true;
	}

	@ConfigItem(
		position = 4,
		keyName = "smoothScaling",
		name = "Smooth scaling",
		description = "Bilinear downscaling. Turn off for nearest-neighbour, which keeps hard pixel edges."
	)
	default boolean smoothScaling()
	{
		return true;
	}

	// ---- Ring ----
	//
	// Only the three protection prayers and their Deflect equivalents get a ring. Combined
	// overheads (RANGE_MAGE, RANGE_MELEE, MAGE_MELEE, RANGE_MAGE_MELEE) have no single correct
	// color, and Smite / Retribution / Redemption / Wrath / Soul Split are not protection prayers
	// at all. Those render ringless rather than guessing.

	@ConfigItem(
		position = 21,
		keyName = "ringEnabled",
		name = "Show ring",
		description = "Draw a colored ring around the icon so it stays readable at small scales.",
		section = RING_SECTION
	)
	default boolean ringEnabled()
	{
		return true;
	}

	@ConfigItem(
		position = 22,
		keyName = "ringThickness",
		name = "Thickness",
		description = "Ring thickness in screen pixels. Constant across scales, so it does not thin out as the icon shrinks.",
		section = RING_SECTION
	)
	@Range(min = 1, max = 6)
	default int ringThickness()
	{
		return 2;
	}

	@ConfigItem(
		position = 23,
		keyName = "ringGap",
		name = "Gap",
		description = "Pixels between the icon edge and the ring.",
		section = RING_SECTION
	)
	@Range(min = 0, max = 10)
	default int ringGap()
	{
		return 2;
	}

	@ConfigItem(
		position = 24,
		keyName = "ringOutline",
		name = "Dark outline",
		description = "Outline the ring in dark grey. Recommended -- without it green is hard to see on grass and blue is hard to see on water.",
		section = RING_SECTION
	)
	default boolean ringOutline()
	{
		return true;
	}

	@ConfigItem(
		position = 25,
		keyName = "palette",
		name = "Color palette",
		description = "Ring colors. The alternatives are chosen for the common forms of color vision deficiency; pick the one that matches your vision, or Custom to set all three yourself.",
		section = RING_SECTION
	)
	default RingPalette palette()
	{
		return RingPalette.STANDARD;
	}

	@ConfigItem(
		position = 26,
		keyName = "distinctStyles",
		name = "Distinct ring styles",
		description = "Also vary the ring's line pattern by prayer type: melee solid, ranged dashed, magic dotted. A cue that does not depend on color at all -- recommended with the Monochrome palette, and useful to anyone.",
		section = RING_SECTION
	)
	default boolean distinctStyles()
	{
		return false;
	}

	// The three pickers below apply only when the palette above is set to Custom. RuneLite has no
	// clean way to hide config items conditionally, so they stay visible and say so instead.

	@Alpha
	@ConfigItem(
		position = 27,
		keyName = "meleeColor",
		name = "Custom: Melee",
		description = "Ring color for Protect from Melee (and Deflect Melee). Used only when the palette is set to Custom.",
		section = RING_SECTION
	)
	default Color meleeColor()
	{
		return new Color(0xFF4136);
	}

	@Alpha
	@ConfigItem(
		position = 28,
		keyName = "rangedColor",
		name = "Custom: Ranged",
		description = "Ring color for Protect from Missiles (and Deflect Missiles). Used only when the palette is set to Custom.",
		section = RING_SECTION
	)
	default Color rangedColor()
	{
		return new Color(0x2ECC40);
	}

	@Alpha
	@ConfigItem(
		position = 29,
		keyName = "magicColor",
		name = "Custom: Magic",
		description = "Ring color for Protect from Magic (and Deflect Magic). Used only when the palette is set to Custom.",
		section = RING_SECTION
	)
	default Color magicColor()
	{
		return new Color(0x2E9BFF);
	}
}

package com.internetter.overheadscalecolor;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Suppresses the client's native overhead icon for the local player and redraws it scaled, with an
 * optional colored ring. See DESIGN.md for the reasoning and the rejected alternatives.
 *
 * The client offers no way to resize an overhead icon, and no way to blank one either --
 * {@code Player} exposes {@code getOverheadIcon()} with no setter. Nor is there a hide flag:
 * {@code Client} has no hide/hidden methods at all in 1.12.38, contrary to a good deal of older
 * material referencing {@code setLocalPlayerHidden2D}. The only available mechanism is a draw veto,
 * which is what the bundled Entity Hider uses (still via the now-deprecated
 * {@code Hooks.RenderableDrawListener}; this uses the current {@link RenderCallback} /
 * {@link RenderCallbackManager} pair that {@code Hooks} delegates to).
 */
@Slf4j
@PluginDescriptor(
	name = "Overhead Scale & Color",
	description = "Cosmetic only. Shrinks your own overhead prayer icon and rings it in a color by prayer type.",
	tags = {"overhead", "prayer", "icon", "scale", "color", "colour", "accessibility"}
)
public class OverheadScaleColorPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	@Inject
	private OverheadScaleColorConfig config;

	@Inject
	private OverheadScaleColorOverlay overlay;

	private final RenderCallback drawCallback = new RenderCallback()
	{
		@Override
		public boolean addEntity(Renderable renderable, boolean drawingUI)
		{
			return shouldDraw(renderable, drawingUI);
		}
	};

	@Provides
	OverheadScaleColorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OverheadScaleColorConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		renderCallbackManager.register(drawCallback);
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(drawCallback);
		overlayManager.remove(overlay);
		overlay.invalidateAll();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (OverheadScaleColorConfig.GROUP.equals(event.getGroup()))
		{
			overlay.invalidate();
		}
	}

	/**
	 * Returning false vetoes the draw.
	 *
	 * {@code drawingUI} true means the client is in its 2D pass for this entity -- name, healthbar,
	 * hitsplats, overhead prayer, overhead chat. The pass is all-or-nothing, which is where this
	 * plugin's one real cost comes from.
	 *
	 * Multiple callbacks compose as a logical AND: {@link RenderCallbackManager#addEntity} returns
	 * false as soon as any registered callback does, and the deprecated Hooks listener path
	 * registers into that same list. So this does not race with Entity Hider; if either vetoes, the
	 * draw is suppressed, and neither can un-veto the other.
	 */
	private boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		if (!drawingUI)
		{
			return true;
		}

		if (!(renderable instanceof Player))
		{
			return true;
		}

		final Player local = client.getLocalPlayer();
		if (local == null || renderable != local)
		{
			return true;
		}

		// Restore everything the moment no overhead is active, so the cost is paid only while
		// there is actually an icon to replace.
		if (config.hideOnlyWhilePraying() && local.getOverheadIcon() == null)
		{
			return true;
		}

		return false;
	}
}
